('public.master_v2_make_checkpoint(uuid,text,text)','{"acl": "{postgres=X/postgres,service_role=X/postgres}", "oid": "31336", "kind": "f", "nargs": 3, "owner": "postgres", "config": ["search_path=\"\""], "secdef": true, "strict": false, "ddl_md5": "67b3acca4af5e8844741cd20a54b2a1f", "nspname": "public", "proname": "master_v2_make_checkpoint", "returns": "uuid", "defaults": null, "language": "plpgsql", "parallel": "u", "arg_modes": null, "arg_names": ["p_session", "p_mode", "p_reason"], "arg_types": "2950 25 25", "arguments": "p_session uuid, p_mode text, p_reason text", "ddl_bytes": 7187, "leakproof": false, "signature": "public.master_v2_make_checkpoint(uuid,text,text)", "ddl_sha256": "d13584d48b1a7d9bbf95c3eb23ccc04dd62080e545b4ffc55ac48b94206da76f", "return_oid": "2950", "source_md5": "dccf4ef166a0bbe466ef683ce88cd8ec", "volatility": "v", "returns_set": false, "source_bytes": 6986, "all_arg_types": null, "source_sha256": "6a297af24641f6d9a007b42b4543cedc6a6cfce6729400f2ff382bf5196fca83", "variadic_type": "0", "default_arg_count": 0}'::jsonb)),
fn AS MATERIALIZED(
 SELECT t.signature,t.expected,p.*,n.nspname,l.lanname,
 pg_get_functiondef(p.oid) actual_ddl,pg_get_userbyid(p.proowner) function_owner
 FROM targets t JOIN pg_proc p ON p.oid=to_regprocedure(t.signature)
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang),
headers AS MATERIALIZED(
 SELECT signature,expected,
 jsonb_build_object('signature',signature,'oid',oid::text,'nspname',nspname,'proname',proname,'kind',prokind::text,
 'owner',function_owner,'acl',proacl::text,'language',lanname,'config',to_jsonb(proconfig),'secdef',prosecdef,
 'volatility',provolatile::text,'parallel',proparallel::text,'strict',proisstrict,'leakproof',proleakproof,
 'arg_types',proargtypes::text,'all_arg_types',to_jsonb(proallargtypes),'arg_modes',to_jsonb(proargmodes),'arg_names',to_jsonb(proargnames),
 'nargs',pronargs,'default_arg_count',pronargdefaults,'defaults',pg_get_expr(proargdefaults,0),
 'variadic_type',provariadic::text,'return_oid',prorettype::text,'returns_set',proretset,
 'arguments',pg_get_function_arguments(oid),'returns',pg_get_function_result(oid),
 'ddl_md5',md5(actual_ddl),'source_md5',md5(prosrc),'ddl_sha256',encode(extensions.digest(convert_to(actual_ddl,'UTF8'),'sha256'),'hex'),
 'source_sha256',encode(extensions.digest(convert_to(prosrc,'UTF8'),'sha256'),'hex'),
 'ddl_bytes',octet_length(actual_ddl),'source_bytes',octet_length(prosrc))h
 FROM fn),
guard AS MATERIALIZED(SELECT count(*)=17 AND bool_and(h=expected)ok FROM headers),index_live AS MATERIALIZED(SELECT jsonb_build_object('oid',ic.oid::text,'schema',ns.nspname,'name',ic.relname,'owner',pg_get_userbyid(ic.relowner),'table_oid',t.oid::text,'table_schema',tn.nspname,'table_name',t.relname,'table_owner',pg_get_userbyid(t.relowner),'table_acl',t.relacl::text,'rls',t.relrowsecurity,'force_rls',t.relforcerowsecurity,'am',am.amname,'unique',i.indisunique,'primary',i.indisprimary,'exclusion',i.indisexclusion,'immediate',i.indimmediate,'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'indkey',i.indkey::text,'indclass',i.indclass::text,'indcollation',i.indcollation::text,'indoption',i.indoption::text,'nkeyatts',i.indnkeyatts,'natts',i.indnatts,'nullsnotdistinct',i.indnullsnotdistinct,'definition',pg_get_indexdef(ic.oid),'predicate',pg_get_expr(i.indpred,i.indrelid),'expressions',pg_get_expr(i.indexprs,i.indrelid),'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(co)ORDER BY co.oid),'[]')FROM pg_constraint co WHERE co.conindid=ic.oid),'dependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('refclassid',d.refclassid::text,'refobjid',d.refobjid::text,'refobjsubid',d.refobjsubid,'deptype',d.deptype::text)ORDER BY d.refclassid,d.refobjid,d.refobjsubid,d.deptype),'[]')FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=ic.oid),'columns',(SELECT jsonb_agg(jsonb_build_object('name',col.attname,'num',col.attnum,'type',col.atttypid::text,'typmod',col.atttypmod,'notnull',col.attnotnull)ORDER BY col.attnum)FROM pg_attribute col WHERE col.attrelid=t.oid AND col.attnum>0 AND NOT col.attisdropped))j FROM pg_class ic JOIN pg_namespace ns ON ns.oid=ic.relnamespace JOIN pg_index i ON i.indexrelid=ic.oid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace tn ON tn.oid=t.relnamespace JOIN pg_am am ON am.oid=ic.relam WHERE ic.oid=to_regclass('public.combat_v2_declarations_difesa_idx')),trigger_live AS MATERIALIZED(SELECT jsonb_build_object('oid',tr.o